%[text] %[text:anchor:T_1FFD3858] # High Voltage Battery - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Charge
mdl = "BatteryHV_harness_model";
load_system(mdl)

% Load model parameters.
BatteryHV_ComponentTestParameters

% Select battery model.
% BatteryHV_useRefsub_Basic
BatteryHV_useRefsub_TableBasedSystem %[output:2b09b4e3]
% Setup simulation case.
BatteryHV_setSimCase_Charge( ... %[output:group:94b09ca2] %[output:77424590]
  CRate = -0.1, ...  Negative value for charge %[output:77424590]
  StateOfCharge_pct = 50 ) %[output:group:94b09ca2] %[output:77424590]
set_param(mdl, StopTime="3600")
% Run simulation.
simOut = sim(mdl);

% Collect logged signals and visualize.
% The basic version of the battery block does not simulate battery temperature.
logged_signals = extractTimetable(simOut.logsout);
BatteryHV_plotResults(logged_signals); %[output:449296dc]
